#!/usr/bin/env bash
#
# Consistency checks for the toolchain versions the image build pins (WI-409).
#
# Each of these drifts silently: the image still builds, just with a different
# tool than the one the repository and the docs say it ships.
#
#   1. The NPM_VERSION and NODE_RUNTIME_VERSION defaults agree between the
#      Dockerfile, docker-compose.yml and .env.example. CI and releases build
#      from the Dockerfile default, `docker compose build` from compose's, and
#      operators copy .env.example.
#   2. No Dockerfile instruction installs or prepares `pnpm@latest`. The
#      frontend build must use the repo's packageManager pin, and the runtime
#      image must never put a global pnpm in front of other repos' pins.
#   3. pnpm-lock.yaml was regenerated by the pnpm that package.json pins.
set -uo pipefail

here="$(cd "$(dirname "$0")" && pwd)"
repo_root="$(cd "$here/../.." && pwd)"
dockerfile="$repo_root/Dockerfile"
compose_file="$repo_root/docker-compose.yml"
env_example="$repo_root/.env.example"
package_json="$repo_root/package.json"
lockfile="$repo_root/pnpm-lock.yaml"

failures=0
fail() { echo "FAIL: $*"; failures=$((failures + 1)); }
pass() { echo "ok: $*"; }

# --- 1. Build-arg defaults agree across the three files. ---------------------
for var in NPM_VERSION NODE_RUNTIME_VERSION; do
  in_dockerfile="$(sed -n "s/^[[:space:]]*ARG[[:space:]]\{1,\}$var=\([^[:space:]]*\).*/\1/p" "$dockerfile" | head -n1)"
  in_compose="$(sed -n "s/.*$var:[[:space:]]*\"\{0,1\}\${$var:\{0,1\}-\([^}]*\)}.*/\1/p" "$compose_file" | head -n1)"
  in_env="$(sed -n "s/^[[:space:]]*#\{0,1\}[[:space:]]*$var=\([^[:space:]]*\).*/\1/p" "$env_example" | head -n1)"

  if [ -z "$in_dockerfile" ] || [ -z "$in_compose" ] || [ -z "$in_env" ]; then
    fail "$var default missing: Dockerfile='$in_dockerfile' compose='$in_compose' .env.example='$in_env'"
  elif [ "$in_dockerfile" != "$in_compose" ] || [ "$in_dockerfile" != "$in_env" ]; then
    fail "$var defaults disagree: Dockerfile='$in_dockerfile' compose='$in_compose' .env.example='$in_env'"
  else
    pass "$var defaults agree ($in_dockerfile)"
  fi
done

# --- 2. No pnpm@latest in any Dockerfile instruction. ------------------------
# Comments may explain why it is gone; only instruction lines count.
latest_lines="$(grep -n 'pnpm@latest' "$dockerfile" | grep -v '^[0-9]*:[[:space:]]*#' || true)"
if [ -n "$latest_lines" ]; then
  fail "Dockerfile still installs or prepares pnpm@latest:"
  echo "$latest_lines"
else
  pass "no Dockerfile instruction uses pnpm@latest"
fi

# --- 3. The lockfile was written by the pinned pnpm. -------------------------
pinned="$(sed -n 's/.*"packageManager"[[:space:]]*:[[:space:]]*"pnpm@\([^"+]*\).*/\1/p' "$package_json" | head -n1)"
# pnpm 11+ records itself under importers['.'].packageManagerDependencies.pnpm.
locked="$(awk '
  /^[[:space:]]*packageManagerDependencies:/ { in_pmd = 1; next }
  in_pmd && /^[[:space:]]*pnpm:/ { in_pnpm = 1; next }
  in_pnpm && /^[[:space:]]*version:/ { v = $2; gsub(/["\047]/, "", v); print v; exit }
  in_pmd && /^[^[:space:]]/ { in_pmd = 0; in_pnpm = 0 }
' "$lockfile")"

if [ -z "$pinned" ]; then
  fail "package.json has no pnpm packageManager pin"
elif [ "$pinned" != "$locked" ]; then
  fail "pnpm-lock.yaml was written by pnpm '${locked:-<none recorded>}', but package.json pins pnpm '$pinned'"
else
  pass "pnpm-lock.yaml matches the packageManager pin ($pinned)"
fi

if [ "$failures" -gt 0 ]; then
  echo "$failures check(s) failed"
  exit 1
fi
echo "all toolchain pin checks passed"
